  "name": "ملحق مخزني",
  "version": "1.0",
  "description": "ملحق مخزني",
  "permissions": ["activeTab"],
  "content_scripts": [
    {
      "matches": ["*://*.amazon.com/*"],
      "js": ["contentScript.js"]
